async function uploadVoucherFile(file, subfolder = "originals") {
  const supabase = createClient();
  const userId = await getActiveUserId() || "anonymous";
  const fileExt = file.name.split(".").pop() || "bin";
  const uniqueName = `${crypto.randomUUID()}.${fileExt}`;
  const path = `vouchers/${userId}/${subfolder}/${uniqueName}`;
  const { error } = await supabase.storage.from("chat-files").upload(path, file, { upsert: false, contentType: file.type || "application/octet-stream" });
  if (error) {
    throw new Error(`Storage upload failed: ${error.message}`);
  }
  const { data: urlData } = supabase.storage.from("chat-files").getPublicUrl(path);
  return urlData.publicUrl;
}
async function uploadVoucherBlob(blob, fileName) {
  const supabase = createClient();
  const userId = await getActiveUserId() || "anonymous";
  const uniqueName = `${crypto.randomUUID()}_${fileName}`;
  const path = `vouchers/${userId}/edited/${uniqueName}`;
  const { error } = await supabase.storage.from("chat-files").upload(path, blob, { upsert: false, contentType: blob.type || "application/octet-stream" });
  if (error) {
    throw new Error(`Invoice storage upload failed: ${error.message}`);
  }
  const { data: urlData } = supabase.storage.from("chat-files").getPublicUrl(path);
  return urlData.publicUrl;
}

