// src/features/chattemplate/extractor/pdf-builder.ts
import { PDFDocument as PDFDocument2 } from "pdf-lib";
async function generateOcrPdf({
  imageFileOrUrl,
  fileName = "Extracted_Text.pdf"
}) {
  if (imageFileOrUrl instanceof File && (imageFileOrUrl.type === "application/pdf" || imageFileOrUrl.name.toLowerCase().endsWith(".pdf"))) {
    const pdfBytes2 = new Uint8Array(await imageFileOrUrl.arrayBuffer());
    const blob2 = new Blob([pdfBytes2], { type: "application/pdf" });
    const blobUrl2 = URL.createObjectURL(blob2);
    return { pdfBytes: pdfBytes2, pdfFile: imageFileOrUrl, blobUrl: blobUrl2 };
  }
  const pdfDoc = await PDFDocument2.create();
  const pageWidth = 595.28;
  const pageHeight = 841.89;
  const margin = 20;
  try {
    let imageBytes;
    if (typeof imageFileOrUrl === "string") {
      const res = await fetch(imageFileOrUrl);
      imageBytes = await res.arrayBuffer();
    } else {
      imageBytes = await imageFileOrUrl.arrayBuffer();
    }
    let embeddedImage;
    const uint8 = new Uint8Array(imageBytes);
    const isPng = uint8[0] === 137 && uint8[1] === 80;
    if (isPng) {
      embeddedImage = await pdfDoc.embedPng(imageBytes);
    } else {
      embeddedImage = await pdfDoc.embedJpg(imageBytes);
    }
    const imgDims = embeddedImage.scaleToFit(pageWidth - margin * 2, pageHeight - margin * 2);
    const imgPage = pdfDoc.addPage([pageWidth, pageHeight]);
    const imgX = (pageWidth - imgDims.width) / 2;
    const imgY = (pageHeight - imgDims.height) / 2;
    imgPage.drawImage(embeddedImage, {
      x: imgX,
      y: imgY,
      width: imgDims.width,
      height: imgDims.height
    });
  } catch (err) {
    console.warn("[pdf-builder] Image embedding failed:", err);
  }
  const pdfBytes = await pdfDoc.save();
  const blob = new Blob([new Uint8Array(pdfBytes)], { type: "application/pdf" });
  const blobUrl = URL.createObjectURL(blob);
  const pdfFile = new File([blob], fileName, { type: "application/pdf" });
  return { pdfBytes, pdfFile, blobUrl };
}

