import { toast as toast11 } from "sonner";
function useOcrExtractor() {
  const [stage, setStage] = useState36("ingest");
  const [selectedFile, setSelectedFile] = useState36(null);
  const [previewUrl, setPreviewUrl] = useState36("");
  const [language, setLanguage] = useState36("eng");
  const [progressPct, setProgressPct] = useState36(0);
  const [progressText, setProgressText] = useState36("");
  const [isProcessing, setIsProcessing] = useState36(false);
  const [ocrResult, setOcrResult] = useState36(null);
  const [editedText, setEditedText] = useState36("");
  const [pdfFile, setPdfFile] = useState36(null);
  const [pdfUrl, setPdfUrl] = useState36("");
  const [isUploading, setIsUploading] = useState36(false);
  const handleFileSelect = useCallback9(async (file) => {
    setSelectedFile(file);
    const url = URL.createObjectURL(file);
    setPreviewUrl(url);
    setStage("ocr_studio");
    setIsProcessing(true);
    setProgressPct(5);
    setProgressText("Preparing document...");
    try {
      const result = await ocrService.recognizeFile(file, "eng", (pct, statusText) => {
        setProgressPct(pct);
        setProgressText(statusText);
      });
      setOcrResult(result);
      setEditedText(JSON.stringify(result.jsonPayload, null, 2));
      toast11.success("Text extracted successfully!");
    } catch (err) {
      toast11.error("Failed to extract text from document");
      console.error("[useOcrExtractor] OCR error:", err);
    } finally {
      setIsProcessing(false);
    }
  }, []);
  const handleLanguageChange = useCallback9(
    async (newLang) => {
      setLanguage(newLang);
      if (!selectedFile) return;
      setIsProcessing(true);
      setProgressPct(5);
      setProgressText(`Loading ${newLang.toUpperCase()} OCR dictionary...`);
      try {
        const result = await ocrService.recognizeFile(selectedFile, newLang, (pct, statusText) => {
          setProgressPct(pct);
          setProgressText(statusText);
        });
        setOcrResult(result);
        setEditedText(JSON.stringify(result.jsonPayload, null, 2));
        toast11.success(`Text re-extracted in ${newLang.toUpperCase()}`);
      } catch (err) {
        toast11.error("Failed to re-extract text");
        console.error("[useOcrExtractor] Re-run error:", err);
      } finally {
        setIsProcessing(false);
      }
    },
    [selectedFile]
  );
  const handleProceedToPdfPreview = useCallback9(async () => {
    if (!selectedFile || !editedText) {
      toast11.error("No document text available to compile PDF");
      return;
    }
    setIsProcessing(true);
    try {
      const timestamp = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
      const defaultName = `Extracted_Text_${timestamp}.pdf`;
      const { pdfFile: generatedFile, blobUrl } = await generateOcrPdf({
        imageFileOrUrl: selectedFile,
        extractedText: editedText,
        fileName: defaultName
      });
      setPdfFile(generatedFile);
      setPdfUrl(blobUrl);
      setStage("pdf_preview");
    } catch (err) {
      toast11.error("Failed to generate PDF");
      console.error("[useOcrExtractor] PDF build error:", err);
    } finally {
      setIsProcessing(false);
    }
  }, [selectedFile, editedText]);
  const handleConfirmSend = useCallback9(
    async (onComplete, customFileName) => {
      if (!pdfFile) return;
      setIsUploading(true);
      try {
        const finalFile = customFileName ? new File([pdfFile], customFileName, { type: "application/pdf" }) : pdfFile;
        const formData = new FormData();
        formData.append("file", finalFile);
        formData.append("folder", "documents");
        const response = await fetch("/api/upload", {
          method: "POST",
          body: formData
        });
        if (!response.ok) {
          const errText = await response.text();
          throw new Error(`Upload failed (${response.status}): ${errText}`);
        }
        const data = await response.json();
        if (!data.success || !data.publicUrl) {
          throw new Error(data.error || "Invalid upload response");
        }
        toast11.success("Document sent successfully!");
        if (onComplete) {
          onComplete({
            fileName: data.fileName || finalFile.name,
            fileSize: data.fileSize || finalFile.size,
            publicUrl: data.publicUrl,
            mimeType: "application/pdf",
            extractedText: editedText,
            extractedJson: ocrResult?.jsonPayload || {}
          });
        }
      } catch (err) {
        toast11.error("Failed to upload and send PDF");
        console.error("[useOcrExtractor] Upload error:", err);
      } finally {
        setIsUploading(false);
      }
    },
    [pdfFile, editedText, ocrResult]
  );
  const reset = useCallback9(() => {
    setStage("ingest");
    setSelectedFile(null);
    setPreviewUrl("");
    setOcrResult(null);
    setEditedText("");
    setPdfFile(null);
    setPdfUrl("");
    setIsProcessing(false);
    setIsUploading(false);
  }, []);
  return {
    stage,
    setStage,
    selectedFile,
    previewUrl,
    language,
    progressPct,
    progressText,
    isProcessing,
    ocrResult,
    editedText,
    setEditedText,
    pdfFile,
    pdfUrl,
    isUploading,
    handleFileSelect,
    handleLanguageChange,
    handleProceedToPdfPreview,
    handleConfirmSend,
    reset
  };
}

