// src/hooks/useCapacitorDocScanner.ts
import { useState as useState38, useCallback as useCallback10 } from "react";
import { toast as toast13 } from "sonner";
function useCapacitorDocScanner() {
  const [isScanning, setIsScanning] = useState38(false);
  const startDocScan = useCallback10(
    async (onSuccess, onFallbackWeb) => {
      if (!nativeScannerService.isPluginAvailable()) {
        if (onFallbackWeb) {
          onFallbackWeb();
        } else {
          toast13.info("Opening document scanner...");
        }
        return;
      }
      setIsScanning(true);
      try {
        const result = await nativeScannerService.scanWithNativeCamera();
        if (result) {
          toast13.success("Document scanned successfully!");
          if (onSuccess) onSuccess(result);
        }
      } catch (err) {
        console.warn("[useCapacitorDocScanner] Native scan error, falling back to document scanner:", err);
        const isUnimplemented = err?.message?.toLowerCase()?.includes("not implemented") || err?.code === "UNIMPLEMENTED" || err?.message?.toLowerCase()?.includes("unimplemented");
        if (isUnimplemented && onFallbackWeb) {
          onFallbackWeb();
        } else if (!isUnimplemented) {
          toast13.error(err.message || "Failed to scan document");
        }
      } finally {
        setIsScanning(false);
      }
    },
    []
  );
  return { isScanning, startDocScan };
}

