          const fileToUpload = msg.attachment_file instanceof File ? msg.attachment_file : new File([msg.attachment_file], msg.attachment_metadata.fileName, { type: msg.attachment_metadata.mimeType });
          const { promise } = uploadAttachment(fileToUpload, userEmail);
          const uploadedUrl = await promise;
          fileUrl = uploadedUrl;
