import { useEffect as useEffect35, useState as useState53, useRef as useRef22, useCallback as useCallback16 } from "react";
function useTypingBroadcast(userId, userName) {
  const [conversationTypingMap, setConversationTypingMap] = useState53({});
  const channelRef = useRef22(null);
  const autoCleanupTimerRef = useRef22(null);
  useEffect35(() => {
    if (!userId) return;
    const supabase = createClient();
    const channel = supabase.channel("chat-typing-room");
    channel.on("broadcast", { event: "typing_status" }, ({ payload }) => {
      if (payload.userId === userId) return;
      const { conversationId, userId: senderId, userName: senderName, status, timestamp } = payload;
      setConversationTypingMap((prevMap) => {
        const existingList = prevMap[conversationId] || [];
        if (status === "idle") {
          const filtered = existingList.filter((u) => u.userId !== senderId);
          if (filtered.length === 0) {
            const newMap = { ...prevMap };
            delete newMap[conversationId];
            return newMap;
          }
          return { ...prevMap, [conversationId]: filtered };
        } else {
          const otherUsers = existingList.filter((u) => u.userId !== senderId);
          const updatedUserState = {
            userId: senderId,
            userName: senderName || "Someone",
            status,
            timestamp
          };
          return {
            ...prevMap,
            [conversationId]: [...otherUsers, updatedUserState]
          };
        }
      });
    }).subscribe();
    channelRef.current = channel;
    autoCleanupTimerRef.current = setInterval(() => {
      const now = Date.now();
      setConversationTypingMap((prevMap) => {
        let hasChanges = false;
        const nextMap = {};
        Object.entries(prevMap).forEach(([convoId, users]) => {
          const freshUsers = users.filter((u) => now - u.timestamp < 4e3);
          if (freshUsers.length !== users.length) {
            hasChanges = true;
          }
          if (freshUsers.length > 0) {
            nextMap[convoId] = freshUsers;
          }
        });
        return hasChanges ? nextMap : prevMap;
      });
    }, 1500);
    return () => {
      if (autoCleanupTimerRef.current) clearInterval(autoCleanupTimerRef.current);
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [userId]);
  const sendTypingStatus = useCallback16(
    (conversationId, status) => {
      if (!userId || !conversationId || !channelRef.current) return;
      const payload = {
        userId,
        userName: userName || "User",
        conversationId,
        status,
        timestamp: Date.now()
      };
      channelRef.current.send({
        type: "broadcast",
        event: "typing_status",
        payload
      });
    },
    [userId, userName]
  );
  const getTypingUsersForConversation = useCallback16(
    (conversationId) => {
      if (!conversationId) return [];
      return conversationTypingMap[conversationId] || [];
    },
    [conversationTypingMap]
  );
  return {
    sendTypingStatus,
    getTypingUsersForConversation,
    conversationTypingMap
  };
}

